// Trains the recoverability classifier used by src/lib/recoverability.ts.
//
// Plain Node, no dependencies, no Python - a hand-rolled logistic regression is more
// than sufficient for a 10-feature problem, and keeps the "single deployable app, no
// second service" property from context/PROJECT_CONTEXT.md §3 intact: this script runs
// once, offline, and writes its output into src/lib/recoverability-model.ts, which the
// Next.js app then imports as plain TypeScript constants - zero runtime ML dependency,
// zero added latency.
//
// The training data is SYNTHETIC, generated by an explicit, documented rule below - not
// real production data (there is none; this is a buildathon demo with no live payments
// account). Same honesty framing already used for src/lib/simulate.ts's demo-only
// batch-outcome simulation: the labeling rule is deliberately legible so the precision/
// recall/AUC this script reports are an honest measurement of "does this classifier
// learn the rule it was shown," not a fabricated number.
//
// Regenerate with: npm run train:model

import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUTPUT_PATH = join(__dirname, "..", "src", "lib", "recoverability-model.ts");

// Must match FailureReason in src/lib/types.ts, in the same order used at inference
// time (src/lib/recoverability.ts) - see the note there.
const FAILURE_REASONS = [
  "insufficient_funds",
  "card_expired",
  "bank_decline",
  "issuer_unavailable",
  "network_error",
  "otp_timeout",
];

const NUMERIC_FEATURES = ["attemptNumber", "customerTenureMonths", "previousSuccessfulPayments", "amount"];

const DATASET_SIZE = 4000;
const VAL_FRACTION = 0.15;
const TEST_FRACTION = 0.15;
const EPOCHS = 1000;

// Grid searched on the validation split below, not fixed guesses - see the "Run" section.
const LEARNING_RATE_GRID = [0.05, 0.1, 0.2];
const L2_LAMBDA_GRID = [0.001, 0.01, 0.05, 0.1];

// --- Synthetic dataset generation -------------------------------------------------

/** Deterministic seeded PRNG (mulberry32) so this script's output is reproducible run to run. */
function makeRng(seed) {
  let a = seed >>> 0;
  return function rng() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rng = makeRng(42);

function randomChoice(arr) {
  return arr[Math.floor(rng() * arr.length)];
}

function randomInt(min, max) {
  return Math.floor(rng() * (max - min + 1)) + min;
}

// A recovery-probability signal per failure reason - transient/no-fault-of-customer
// reasons (network hiccup, issuer outage) are more recoverable than reasons requiring
// real customer action (expired card, insufficient funds, repeated OTP friction).
const REASON_BIAS = {
  insufficient_funds: 0.1,
  card_expired: -0.1,
  bank_decline: -0.3,
  issuer_unavailable: 0.4,
  network_error: 0.6,
  otp_timeout: -0.4,
};

function generateRow() {
  const failureReason = randomChoice(FAILURE_REASONS);
  const attemptNumber = randomInt(1, 3);
  const customerTenureMonths = randomInt(0, 36);
  const previousSuccessfulPayments = randomInt(0, 20);
  const amount = randomInt(500, 8000);

  return { failureReason, attemptNumber, customerTenureMonths, previousSuccessfulPayments, amount };
}

// --- Feature engineering -----------------------------------------------------------

function computeStats(rows, key) {
  const values = rows.map((r) => r[key]);
  const mean = values.reduce((s, v) => s + v, 0) / values.length;
  const variance = values.reduce((s, v) => s + (v - mean) ** 2, 0) / values.length;
  return { mean, std: Math.sqrt(variance) || 1 };
}

function buildFeatureVector(row, numericStats) {
  const numeric = NUMERIC_FEATURES.map((key) => {
    const { mean, std } = numericStats[key];
    return (row[key] - mean) / std;
  });
  const oneHot = FAILURE_REASONS.map((r) => (row.failureReason === r ? 1 : 0));
  return [...numeric, ...oneHot];
}

// Label generation - explicit, legible rule (not real production data, see header).
function labelRow(row) {
  const z = (key, mean, std) => (row[key] - mean) / std;
  // Rough population-level stats for a believable logit, independent of the actual
  // train/test split's computed stats (this is the ground-truth generating process,
  // not a feature the model gets to see pre-normalized by).
  const logit =
    1.1 * z("customerTenureMonths", 18, 11) +
    0.9 * z("previousSuccessfulPayments", 10, 6) -
    1.3 * z("attemptNumber", 2, 0.8) -
    0.3 * z("amount", 4250, 2200) +
    REASON_BIAS[row.failureReason] +
    (rng() - 0.5) * 0.6; // unmodeled noise - keeps this a real classification problem, not a lookup table
  const probability = 1 / (1 + Math.exp(-logit));
  return rng() < probability ? 1 : 0;
}

// --- Logistic regression (batch gradient descent, L2-regularized) ------------------

function sigmoid(x) {
  return 1 / (1 + Math.exp(-x));
}

function trainLogisticRegression(X, y, numFeatures, learningRate, l2Lambda, epochs) {
  let weights = new Array(numFeatures).fill(0);
  let bias = 0;
  const n = X.length;

  for (let epoch = 0; epoch < epochs; epoch++) {
    const gradW = new Array(numFeatures).fill(0);
    let gradB = 0;

    for (let i = 0; i < n; i++) {
      const pred = sigmoid(dot(X[i], weights) + bias);
      const error = pred - y[i];
      for (let f = 0; f < numFeatures; f++) gradW[f] += error * X[i][f];
      gradB += error;
    }

    for (let f = 0; f < numFeatures; f++) {
      weights[f] -= learningRate * (gradW[f] / n + l2Lambda * weights[f]);
    }
    bias -= learningRate * (gradB / n);
  }

  return { weights, bias };
}

function dot(a, b) {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
}

// --- Metrics -------------------------------------------------------------------------

function evaluate(X, y, weights, bias) {
  const predictions = X.map((row) => sigmoid(dot(row, weights) + bias));
  const predictedLabels = predictions.map((p) => (p >= 0.5 ? 1 : 0));

  let tp = 0, fp = 0, tn = 0, fn = 0;
  for (let i = 0; i < y.length; i++) {
    if (predictedLabels[i] === 1 && y[i] === 1) tp++;
    else if (predictedLabels[i] === 1 && y[i] === 0) fp++;
    else if (predictedLabels[i] === 0 && y[i] === 0) tn++;
    else fn++;
  }

  const precision = tp + fp === 0 ? 0 : tp / (tp + fp);
  const recall = tp + fn === 0 ? 0 : tp / (tp + fn);
  const accuracy = (tp + tn) / y.length;
  const auc = computeAUC(predictions, y);

  return { precision, recall, accuracy, auc };
}

/** Mann-Whitney U / rank-based AUC - no external stats library needed. */
function computeAUC(predictions, labels) {
  const indexed = predictions.map((p, i) => ({ p, label: labels[i] }));
  indexed.sort((a, b) => a.p - b.p);

  // Assign average rank to ties.
  const ranks = new Array(indexed.length);
  let i = 0;
  while (i < indexed.length) {
    let j = i;
    while (j + 1 < indexed.length && indexed[j + 1].p === indexed[i].p) j++;
    const avgRank = (i + j) / 2 + 1; // 1-indexed
    for (let k = i; k <= j; k++) ranks[k] = avgRank;
    i = j + 1;
  }

  let sumRanksPositive = 0;
  let nPos = 0;
  let nNeg = 0;
  for (let idx = 0; idx < indexed.length; idx++) {
    if (indexed[idx].label === 1) {
      sumRanksPositive += ranks[idx];
      nPos++;
    } else {
      nNeg++;
    }
  }

  if (nPos === 0 || nNeg === 0) return 0.5;
  return (sumRanksPositive - (nPos * (nPos + 1)) / 2) / (nPos * nNeg);
}

// --- Run -------------------------------------------------------------------------
//
// Three-way split, not just train/test: the validation slice is used to grid-search
// learning rate and L2 regularization strength (a real fine-tuning step, not fixed
// guesses), and the final reported precision/recall/AUC come from the test slice, which
// neither training nor hyperparameter selection ever touches.

const rows = Array.from({ length: DATASET_SIZE }, generateRow);
const labels = rows.map(labelRow);

const trainEnd = Math.floor(DATASET_SIZE * (1 - VAL_FRACTION - TEST_FRACTION));
const valEnd = Math.floor(DATASET_SIZE * (1 - TEST_FRACTION));

const trainRows = rows.slice(0, trainEnd);
const trainLabels = labels.slice(0, trainEnd);
const valRows = rows.slice(trainEnd, valEnd);
const valLabels = labels.slice(trainEnd, valEnd);
const testRows = rows.slice(valEnd);
const testLabels = labels.slice(valEnd);

// Normalization stats come from the TRAIN split only, to avoid leaking val/test
// information into the features - applied identically to all three splits, and shipped
// in the generated output so runtime inference uses the exact same stats.
const numericStats = {};
for (const key of NUMERIC_FEATURES) numericStats[key] = computeStats(trainRows, key);

const trainX = trainRows.map((r) => buildFeatureVector(r, numericStats));
const valX = valRows.map((r) => buildFeatureVector(r, numericStats));
const testX = testRows.map((r) => buildFeatureVector(r, numericStats));

const numFeatures = NUMERIC_FEATURES.length + FAILURE_REASONS.length;

let best = null;
for (const learningRate of LEARNING_RATE_GRID) {
  for (const l2Lambda of L2_LAMBDA_GRID) {
    const { weights, bias } = trainLogisticRegression(trainX, trainLabels, numFeatures, learningRate, l2Lambda, EPOCHS);
    const valMetrics = evaluate(valX, valLabels, weights, bias);
    if (!best || valMetrics.auc > best.valAuc) {
      best = { learningRate, l2Lambda, weights, bias, valAuc: valMetrics.auc };
    }
  }
}

console.log(
  `Best hyperparameters (by validation AUC): learningRate=${best.learningRate} l2Lambda=${best.l2Lambda} ` +
    `(val AUC ${best.valAuc.toFixed(3)})`
);

// Refit on train+val combined with the winning hyperparameters, same pattern as a
// standard train/val/test workflow - val's only job was picking the hyperparameters, so
// folding it back in for the final fit doesn't leak test information and uses more data.
const finalX = trainX.concat(valX);
const finalLabels = trainLabels.concat(valLabels);
const { weights, bias } = trainLogisticRegression(
  finalX,
  finalLabels,
  numFeatures,
  best.learningRate,
  best.l2Lambda,
  EPOCHS
);
const metrics = evaluate(testX, testLabels, weights, bias);

console.log("Recoverability model trained.");
console.log(
  `Dataset: ${DATASET_SIZE} rows (${trainRows.length} train / ${valRows.length} val / ${testRows.length} test)`
);
console.log(
  `Held-out test metrics: precision=${metrics.precision.toFixed(3)} recall=${metrics.recall.toFixed(3)} ` +
    `accuracy=${metrics.accuracy.toFixed(3)} auc=${metrics.auc.toFixed(3)}`
);

const output = `// AUTO-GENERATED by scripts/train-recoverability-model.mjs - do not hand-edit.
// Regenerate with: npm run train:model
//
// Trained on a synthetic labeled dataset (see the script for the labeling rule) since
// this buildathon build has no live payments account / real recovery outcome history.
// Precision/recall/AUC below are honest measurements against a held-out ${Math.round(TEST_FRACTION * 100)}%
// test split that never touches training or hyperparameter selection (a separate
// ${Math.round(VAL_FRACTION * 100)}% validation split, folded back into the final fit after being used only
// to grid-search learning rate/L2 strength, handles that) - they describe how well the
// model learned the documented rule, not a claim about real-world recovery rates.

export const MODEL_WEIGHTS = {
  numericFeatures: ${JSON.stringify(NUMERIC_FEATURES)} as const,
  numericStats: ${JSON.stringify(numericStats, null, 2)},
  failureReasonCategories: ${JSON.stringify(FAILURE_REASONS)} as const,
  weights: ${JSON.stringify(weights)},
  bias: ${bias},
};

export const MODEL_METRICS = {
  precision: ${metrics.precision},
  recall: ${metrics.recall},
  accuracy: ${metrics.accuracy},
  auc: ${metrics.auc},
  datasetSize: ${DATASET_SIZE},
  trainSize: ${trainRows.length + valRows.length},
  testSize: ${testRows.length},
  hyperparameters: {
    learningRate: ${best.learningRate},
    l2Lambda: ${best.l2Lambda},
    epochs: ${EPOCHS},
    selectedByValidationAuc: ${best.valAuc},
  },
  trainedAt: ${JSON.stringify(new Date().toISOString())},
};
`;

writeFileSync(OUTPUT_PATH, output, "utf-8");
console.log(`Wrote ${OUTPUT_PATH}`);
